def transform(grid):
    # Background becomes 0, while the sparse marks become the background color.
    colors = {v for row in grid for v in row}
    background = max(colors, key=lambda c: sum(row.count(c) for row in grid))
    return [[0 if v == background else background for v in row] for row in grid]

